def canBalanceWithOneMove(nums):
    n = len(nums)
    total = sum(nums)
    left_vals = set()
    right_cnt = {}
    for x in nums:
        right_cnt[x] = right_cnt.get(x, 0) + 1
    L = 0
    for p in range(1, n):
        x = nums[p - 1]
        L += x
        left_vals.add(x)
        right_cnt[x] -= 1
        d = L - (total - L)
        if d == 0:
            return True
        if d % 2:
            continue
        h = d // 2
        if p >= 2 and h in left_vals:
            return True
        if n - p >= 2 and right_cnt.get(-h, 0) > 0:
            return True
    return False
